import React, { useRef, useEffect, useState } from 'react';
import { Canvas, useThree } from '@react-three/fiber';
import { OrbitControls, AsciiRenderer } from '@react-three/drei';
import { STLLoader } from 'three/examples/jsm/loaders/STLLoader';
import * as THREE from 'three';

export default function App() {
  return (
    <div style={{ height: '100vh', width: '100vw', background: '#282c34' }}>
      <Canvas camera={{ position: [0, 0, 10], fov: 45 }}>
        {/* Camera controls */}
        <OrbitControls />
        {/* Load and display the STL model */}
        <ResponsiveSTLModel path="./stls/model.stl" />
        {/* ASCII Renderer */}
        <AsciiRenderer invert />
      </Canvas>
    </div>
  );
}

// Responsive STL Model Component
function ResponsiveSTLModel({ path }) {
  const [geometry, setGeometry] = useState(null);
  const meshRef = useRef();
  const { size } = useThree();

  useEffect(() => {
    const loader = new STLLoader();
    loader.load(
      path,
      (loadedGeometry) => {
        loadedGeometry.center(); // Center the model in the scene
        setGeometry(loadedGeometry);
      },
      undefined,
      (error) => {
        console.error('Error loading STL file:', error);
      }
    );
  }, [path]);

  // Adjust the scale to fit within the viewport width
  useEffect(() => {
    if (geometry && meshRef.current) {
      const box = new THREE.Box3().setFromObject(meshRef.current);
      const size = new THREE.Vector3();
      box.getSize(size);

      // Calculate scaling factor to fit model within the viewport
      const maxDim = Math.max(size.x, size.y, size.z);
      const scaleFactor = Math.min(8 / maxDim, 1); // Ensure it scales to fit within the scene

      meshRef.current.scale.set(scaleFactor, scaleFactor, scaleFactor);
    }
  }, [geometry, size]);

  if (!geometry) return null;

  return (
    <mesh ref={meshRef} geometry={geometry}>
      {/* Wireframe Material */}
      <meshStandardMaterial color="lightblue" wireframe />
      <pointLight position={[10, 10, 10]} />
      <ambientLight intensity={0.5} />
    </mesh>
  );
}
